-- 1. userId=7350017 (小段): pack_500 积分包，+500购买积分
UPDATE users SET creditsPurchased = creditsPurchased + 500, updatedAt = NOW() WHERE id = 7350017;

-- 2. userId=9030001: basic订阅，设置订阅积分为750，重置日期30天后
UPDATE users SET creditsSubscription = 750, creditsResetDate = DATE_ADD(NOW(), INTERVAL 30 DAY), updatedAt = NOW() WHERE id = 9030001;

-- 3. userId=18360001 (商业智慧): basic订阅，设置订阅积分为750，重置日期30天后
UPDATE users SET creditsSubscription = 750, creditsResetDate = DATE_ADD(NOW(), INTERVAL 30 DAY), updatedAt = NOW() WHERE id = 18360001;

-- 4. 创建订阅记录 for userId=9030001
INSERT INTO subscriptions (userId, plan, monthlyLimit, price, status, startDate, endDate, createdAt, updatedAt)
VALUES (9030001, 'basic', 750, 9900, 'active', NOW(), DATE_ADD(NOW(), INTERVAL 30 DAY), NOW(), NOW())
ON DUPLICATE KEY UPDATE plan='basic', status='active', endDate=DATE_ADD(NOW(), INTERVAL 30 DAY), updatedAt=NOW();

